begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data) values
 ('00000000-0000-0000-0000-000000000011','authenticated','authenticated','invoice-owner@test.local','','{}','{}'),
 ('00000000-0000-0000-0000-000000000012','authenticated','authenticated','invoice-driver@test.local','','{}','{}');
insert into public.companies(id,legal_name,display_name,created_by) values('10000000-0000-0000-0000-000000000011','Invoice Test LLC','Invoice Test','00000000-0000-0000-0000-000000000011');
insert into public.company_memberships(company_id,user_id,role) values
 ('10000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000011','owner'),
 ('10000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000012','driver');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000011';
select lives_ok($$select * from public.save_invoice('10000000-0000-0000-0000-000000000011',null,'BlueLine','2026-09-01','2026-10-01','sent','POD attached','[{"description":"Freight","quantity":2,"unitPrice":1000,"taxRate":0.05}]','90000000-0000-0000-0000-000000000001')$$,'invoice issues atomically');
select is((select total from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),2100.00::numeric,'invoice total includes tax');
select is((select count(*) from public.journal_entries where company_id='10000000-0000-0000-0000-000000000011' and status='posted'),1::bigint,'issued invoice posts ledger');
select lives_ok($$select * from public.save_invoice('10000000-0000-0000-0000-000000000011',null,'BlueLine','2026-09-01','2026-10-01','sent','POD attached','[{"description":"Freight","quantity":2,"unitPrice":1000,"taxRate":0.05}]','90000000-0000-0000-0000-000000000001')$$,'lost-response retry returns original invoice');
select is((select count(*) from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),1::bigint,'invoice retry does not duplicate');
select throws_ok($$select * from public.save_invoice('10000000-0000-0000-0000-000000000011',null,'Different','2026-09-01','2026-10-01','sent','POD attached','[{"description":"Freight","quantity":2,"unitPrice":1000,"taxRate":0.05}]','90000000-0000-0000-0000-000000000001')$$,'P0001','Invoice request ID was already used for different data','changed retry payload rejected');
insert into public.chart_of_accounts(company_id,account_number,name,account_type) values('10000000-0000-0000-0000-000000000011','1000','Cash','asset');
select lives_ok($$select public.record_invoice_payment('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',500,(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000011' and account_number='1000'),'Deposit','90000000-0000-0000-0000-000000000002')$$,'dated partial payment posts');
select lives_ok($$select public.record_invoice_payment('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',500,(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000011' and account_number='1000'),'Deposit','90000000-0000-0000-0000-000000000002')$$,'payment retry succeeds');
select is((select count(*) from public.payments where company_id='10000000-0000-0000-0000-000000000011'),1::bigint,'payment retry does not duplicate');
select lives_ok($$select public.record_invoice_credit('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',210,'Rate correction','90000000-0000-0000-0000-000000000003')$$,'credit posts proportionate tax reversal');
select lives_ok($$select public.record_invoice_credit('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',210,'Rate correction','90000000-0000-0000-0000-000000000003')$$,'credit retry succeeds');
select is((select tax_amount from public.credit_notes where company_id='10000000-0000-0000-0000-000000000011'),10::numeric,'credit reverses tax proportionately');
select is((select count(*) from public.journal_entries where company_id='10000000-0000-0000-0000-000000000011'),3::bigint,'invoice payment and credit each have one journal');
select throws_ok($$select public.record_invoice_payment('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',1600,(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000011' and account_number='1000'),'Too much',gen_random_uuid())$$,'P0001','Payment exceeds outstanding invoice balance','overpayment rejected');
select lives_ok($$select public.record_invoice_payment('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',1390,(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000011' and account_number='1000'),'Final',gen_random_uuid())$$,'final payment posts');
select is((select status from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'paid','allocations settle invoice');
select lives_ok($$select public.record_invoice_credit('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',105,'Post-payment credit',gen_random_uuid())$$,'credit after payment preserves customer credit balance');
select is((select sum(l.debit-l.credit) from public.journal_lines l join public.chart_of_accounts a on a.id=l.account_id where l.company_id='10000000-0000-0000-0000-000000000011' and a.account_number='1100'),-105::numeric,'customer credit is visible in receivables control account');
select throws_ok($$update public.invoices set status='draft' where company_id='10000000-0000-0000-0000-000000000011'$$,'P0001','Issued invoices cannot be reopened as drafts','cannot reopen issued invoice');
select throws_ok($$update public.invoice_items set quantity=3 where company_id='10000000-0000-0000-0000-000000000011'$$,'P0001','Issued invoice lines require a credit note or a new invoice','cannot rewrite posted invoice lines');
select throws_ok($$delete from public.invoices where company_id='10000000-0000-0000-0000-000000000011'$$,'P0001','Only draft invoices can be deleted','cannot delete issued invoice');
select throws_ok($$update public.payments set amount=1 where company_id='10000000-0000-0000-0000-000000000011'$$,'P0001','Customer payments and credits are immutable','payment cannot be edited');
select throws_ok($$delete from public.credit_notes where company_id='10000000-0000-0000-0000-000000000011'$$,'P0001','Customer payments and credits are immutable','credit cannot be deleted');
select throws_ok($$select public.reverse_journal_entry('10000000-0000-0000-0000-000000000011',(select journal_entry_id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),90001,'2026-09-03')$$,'P0001','Use the receivables correction workflow for invoice journals','ledger-only reversal cannot break subledger');
insert into public.accounting_periods(company_id,starts_on,ends_on,closed_at,closed_by) values('10000000-0000-0000-0000-000000000011','2026-09-03','2026-09-03',now(),auth.uid());
select throws_ok($$select public.record_invoice_credit('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-03',10,'Closed period',gen_random_uuid())$$,'P0001','Accounting period is closed','failed posting rolls back credit');
select is((select count(*) from public.credit_notes where company_id='10000000-0000-0000-0000-000000000011'),2::bigint,'no partial credit record remains after failed journal');
select throws_ok($$update public.invoices set subtotal=1 where company_id='10000000-0000-0000-0000-000000000011'$$,'P0001','Issued invoices require a credit note or a new invoice','posted invoice header cannot be rewritten');
select throws_ok($$select public.record_invoice_credit('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-08-31',1,'Too early',gen_random_uuid())$$,'P0001','Allocation date must be between invoice date and today','credits cannot predate the invoice');
select throws_ok($$select public.record_invoice_credit('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',211,'Rate correction','90000000-0000-0000-0000-000000000003')$$,'P0001','Credit request ID was already used for different data','credit retry cannot change amount');
select throws_ok($$select public.record_invoice_payment('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',501,(select id from public.chart_of_accounts where company_id='10000000-0000-0000-0000-000000000011' and account_number='1000'),'Deposit','90000000-0000-0000-0000-000000000002')$$,'P0001','Payment request ID was already used for different data','payment retry cannot change amount');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000012';
select throws_ok($$select public.record_invoice_credit('10000000-0000-0000-0000-000000000011',(select id from public.invoices where company_id='10000000-0000-0000-0000-000000000011'),'2026-09-02',1,'Denied',gen_random_uuid())$$,'P0001','Finance access required','driver cannot create credits');
select * from finish();rollback;
